<?php
declare(strict_types=1);
return static function(PDO $pdo):void{
    foreach(['bdc_dance_cup','bdc_test_dance_cup'] as $p){
        $pdo->exec("CREATE TABLE IF NOT EXISTS {$p}_judge_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,competition_id BIGINT UNSIGNED NOT NULL,judge_assignment_id BIGINT UNSIGNED NOT NULL,access_token CHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'not_started',started_at DATETIME NULL,submitted_at DATETIME NULL,last_seen_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_dc_session_judge(competition_id,judge_assignment_id),UNIQUE KEY uq_dc_session_token(access_token),INDEX idx_dc_session_status(competition_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $pdo->exec("CREATE TABLE IF NOT EXISTS {$p}_event_projection(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,active_competition_id BIGINT UNSIGNED NOT NULL,active_entry_id BIGINT UNSIGNED NULL,access_token CHAR(64) NOT NULL,screen_type VARCHAR(30) NOT NULL DEFAULT 'holding',theme VARCHAR(30) NOT NULL DEFAULT 'midnight_wine',holding_title VARCHAR(190) NOT NULL DEFAULT 'Dance Cup',holding_message VARCHAR(255) NOT NULL DEFAULT 'Next contestant preparing',contestant_seconds INT UNSIGNED NOT NULL DEFAULT 12,holding_seconds INT UNSIGNED NOT NULL DEFAULT 8,auto_cycle TINYINT(1) NOT NULL DEFAULT 0,state_version BIGINT UNSIGNED NOT NULL DEFAULT 1,updated_by BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_dc_event_projection(event_id),UNIQUE KEY uq_dc_event_projection_token(access_token)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }
};
